<?php
namespace App\Services;use App\Models\ResourceRevision;use App\Models\User;use Illuminate\Http\Exceptions\HttpResponseException;use Illuminate\Validation\ValidationException;
final class RevisionConflictService{
public function latest(string $type,int|string $id,bool $lock=false):?ResourceRevision{$q=ResourceRevision::where('resource_type',$type)->where('resource_id',$id)->orderByDesc('revision_number');if($lock)$q->lockForUpdate();return $q->with('author:id,name')->first();}
public function assertBase(User $user,string $type,int|string $id,int|string|null $baseId,bool $lock=true,bool $required=false):?ResourceRevision{$latest=$this->latest($type,$id,$lock);if(!$latest)return null;if($baseId===null){if($required)throw ValidationException::withMessages(['base_revision_id'=>['The current base revision is required. Reload before saving.']]);return $latest;}$base=ResourceRevision::find($baseId);if(!$base||$base->resource_type!==$type||(string)$base->resource_id!==(string)$id)throw ValidationException::withMessages(['base_revision_id'=>['Base revision must belong to this resource.']]);if($base->id!==$latest->id)throw new HttpResponseException(response()->json(['message'=>'A newer revision was created while you were editing.','code'=>'revision_conflict','resource'=>['type'=>$type,'id'=>(string)$id],'submittedBaseRevision'=>$this->revision($base),'latestRevision'=>$this->revision($latest),'latestContributor'=>$latest->author?['id'=>(string)$latest->author->id,'name'=>$latest->author->name]:null,'latestUpdatedAt'=>$latest->created_at->toISOString(),'changedSections'=>ResourceRevision::where('resource_type',$type)->where('resource_id',$id)->where('revision_number','>',$base->revision_number)->get()->flatMap(fn($r)=>$r->changed_sections)->unique()->values(),'canSaveDraft'=>true,'canReviewChanges'=>true,'canDiscardAndPull'=>true],409));return $latest;}
private function revision(ResourceRevision $r):array{return ['id'=>(string)$r->id,'revisionNumber'=>$r->revision_number,'createdAt'=>$r->created_at->toISOString()];}}
